func schemaContract(t *testing.T) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "..", contractPath))
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

func TestContractIndependentCountsAndSemantics(t *testing.T) {
	layout, err := parseContract(schemaContract(t))
	if err != nil {
		t.Fatal(err)
	}
	// Independently reviewed counts, not generated by the parser or the JSON file.
	oracle := []struct {
		name                    string
		nongenerated, generated int
	}{
		{"pp_operation_roots", 11, 0}, {"pp_root_steps", 5, 18},
		{"pp_request_origins", 32, 1}, {"pp_request_heads", 4, 0},
		{"pp_attempt_origins", 29, 1}, {"pp_attempt_heads", 6, 0},
		{"pp_attempt_nodes", 9, 1}, {"pp_account_origins", 9, 1},
		{"pp_account_heads", 12, 0}, {"pp_account_journal", 54, 4},
		{"pp_account_command_sources", 23, 1}, {"pp_attempt_delivery_sources", 15, 1},
		{"pp_incoming_sources", 25, 1}, {"pp_meter_choices", 15, 1},
		{"pp_meter_origins", 6, 1}, {"pp_conflict_sources", 10, 1},
		{"pp_request_decisions", 19, 2}, {"pp_normal_cost_decisions", 28, 1},
		{"pp_cost_mutations", 13, 6}, {"pp_cost_reset_decisions", 12, 3},
		{"pp_evidence_choices", 35, 1}, {"pp_evidence_members", 11, 2},
		{"pp_procurement_transitions", 36, 5}, {"pp_proposal_births", 22, 1},
		{"pp_approval_consumptions", 39, 1}, {"pp_unmanaged_correction_sources", 21, 1},
		{"pp_recovery_sources", 21, 1}, {"pp_cost_outbox_links", 10, 4},
		{"pp_reconciliation_sources", 45, 1}, {"pp_customer_finish_outcomes", 46, 1},
		{"pp_customer_finish_ledger_effects", 13, 1}, {"pp_customer_finish_pb_effects", 11, 1},
	}
	if layout.Schema != 1 || layout.Status != layoutStatus || layout.Source != contractPath || layout.TableCount != 32 || layout.ColumnCount != 711 || layout.GeneratedColumnCount != 64 || layout.NongeneratedColumnCount != 647 {
		t.Fatalf("wrong manifest metadata/counts: %+v", layout)
	}
	if len(layout.Tables) != len(oracle) {
		t.Fatalf("got %d tables", len(layout.Tables))
	}
	for i, want := range oracle {
		got := layout.Tables[i]
		if got.Name != want.name || got.NongeneratedColumnCount != want.nongenerated || got.GeneratedColumnCount != want.generated || got.ColumnCount != want.nongenerated+want.generated || len(got.Columns) != got.ColumnCount {
			t.Errorf("table %d: got %s %d/%d/%d, want %s %d/%d", i, got.Name, got.NongeneratedColumnCount, got.GeneratedColumnCount, got.ColumnCount, want.name, want.nongenerated, want.generated)
		}
	}
	checks := []struct {
		table, name, typeName string
		nullable              bool
		expression            string
	}{
		{"pp_operation_roots", "created_xid", "XID8", false, ""},
		{"pp_operation_roots", "session_role_oid", "OID", false, ""},
		{"pp_request_origins", "step_kind", "TEXT", false, "'request_birth'::text"},
		{"pp_request_origins", "client_ip", "TEXT", true, ""},
		{"pp_request_origins", "request_deadline", "TIMESTAMPTZ", false, ""},
		{"pp_attempt_origins", "sequence", "INTEGER", false, ""},
		{"pp_attempt_origins", "route_decisions", "JSONB", false, ""},
		{"pp_attempt_origins", "cost_version_id", "TEXT", true, ""},
		{"pp_attempt_origins", "cost_input_rate", "BIGINT", true, ""},
		{"pp_attempt_origins", "cost_basis", "TEXT", false, ""},
		{"pp_attempt_origins", "quote_selected_at", "TIMESTAMPTZ", false, ""},
		{"pp_account_origins", "version", "SMALLINT", false, ""},
		{"pp_account_heads", "held_amount", "NUMERIC(100,0)", false, ""},
		{"pp_account_heads", "configuration_revision", "BIGINT", false, ""},
		{"pp_account_journal", "before_configuration_revision", "BIGINT", true, ""},
		{"pp_account_journal", "before_held_amount", "NUMERIC(100,0)", true, ""},
		{"pp_account_journal", "after_spent_amount", "NUMERIC(100,0)", false, ""},
		{"pp_account_journal", "command_operation_id", "TEXT", true, "CASE WHEN source_kind = 'command' THEN source_id ELSE NULL END"},
		{"pp_account_journal", "dispatch_attempt_id", "TEXT", true, "CASE WHEN source_kind = 'dispatch' THEN source_id ELSE NULL END"},
		{"pp_incoming_sources", "step_kind", "TEXT", false, "'incoming'::text"},
		{"pp_incoming_sources", "tenant_id", "TEXT", false, ""},
		{"pp_incoming_sources", "request_id", "TEXT", false, ""},
		{"pp_incoming_sources", "attempt_id", "TEXT", true, ""},
		{"pp_incoming_sources", "input_tokens", "BIGINT", false, ""},
		{"pp_incoming_sources", "raw_content_written", "BOOLEAN", false, ""},
		{"pp_reconciliation_sources", "input_usage_status", "TEXT", true, ""},
		{"pp_reconciliation_sources", "input_input_tokens", "BIGINT", true, ""},
		{"pp_reconciliation_sources", "case_reasoning_tokens", "BIGINT", true, ""},
		{"pp_procurement_transitions", "before_revision", "BIGINT", true, ""},
		{"pp_procurement_transitions", "after_revision", "BIGINT", false, ""},
		{"pp_procurement_transitions", "before_anomaly", "BOOLEAN", true, ""},
		{"pp_procurement_transitions", "after_anomaly", "BOOLEAN", false, ""},
		{"pp_cost_mutations", "d_approval_consumed", "TEXT", true, "CASE WHEN cause_kind = 'approval_consumed' THEN cause_source_id ELSE NULL END"},
		{"pp_root_steps", "d_request_birth", "TEXT", true, "CASE WHEN kind = 'request_birth' THEN source_id ELSE NULL END"},
		{"pp_attempt_nodes", "previous_ordinal", "BIGINT", false, "ordinal - 1"},
		{"pp_evidence_members", "previous_member_ordinal", "BIGINT", false, "member_ordinal - 1"},
		{"pp_meter_origins", "source_id", "TEXT", false, ""},
		{"pp_meter_origins", "step_kind", "TEXT", false, "'meter_choice'::text"},
	}
	for _, want := range checks {
		got := findColumn(t, layout, want.table, want.name)
		expression := ""
		if got.GeneratedExpression != nil {
			expression = *got.GeneratedExpression
		}
		if got.Type != want.typeName || got.Nullable != want.nullable || expression != want.expression || (want.expression == "") != (got.GeneratedExpression == nil) {
			t.Errorf("%s.%s got %+v expression=%q, want %s nullable=%v expression=%q", want.table, want.name, got, expression, want.typeName, want.nullable, want.expression)
		}
	}
	if got := layout.Tables[1].Columns; got[5].Name != "d_request_birth" || got[len(got)-1].Name != "d_reconciliation" {
		t.Error("root generated columns lost declared order")
	}
	journal := layout.Tables[9].Columns
	if journal[4].Name != "previous_ordinal" || journal[len(journal)-3].Name != "command_operation_id" {
		t.Error("inline generated placeholders were moved or duplicated")
	}
}

func findColumn(t *testing.T, layout manifest, tableName, columnName string) column {
	t.Helper()
	for _, tbl := range layout.Tables {
		if tbl.Name == tableName {
			for _, col := range tbl.Columns {
				if col.Name == columnName {
					return col
				}
			}
		}
	}
	t.Fatalf("missing %s.%s", tableName, columnName)
	return column{}
}

func TestStrictContractRejections(t *testing.T) {
	source := schemaContract(t)
	tableRow := "| pp_operation_roots | id:T,entry_kind:T,scope_kind:T,tenant_id:T?,request_id:T?,attempt_id:T?,account_target_id:T?,created_xid:X,session_role_oid:O,step_count:I,semantic_result:T |"
	genRow := "| pp_root_steps | d_request_birth | CASE WHEN kind = 'request_birth' THEN source_id ELSE NULL END |"
	macroRow := "| S(k) | id:T,root_id:T,step_no:I,step_kind:T generated(k),created_xid:X |"
	cases := []struct {
		name, old, replacement, errorPart string
	}{
		{"duplicate table", "| pp_root_steps | root_id:T", "| pp_operation_roots | root_id:T", "duplicate table"},
		{"missing table", tableRow + "\n", "", "exactly 32"},
		{"duplicate column", "step_count:I,semantic_result:T", "step_count:I,step_count:I,semantic_result:T", "duplicate column"},
		{"duplicate macro", macroRow, macroRow + "\n" + macroRow, "duplicate macro"},
		{"missing macro", "| A? | tenant_id:T,request_id:T,attempt_id:T? |\n", "", "missing macro"},
		{"unknown macro definition", "| Q | cost_version_id:", "| Z | cost_version_id:", "unknown macro definition"},
		{"unknown macro use", "F(before)?", "Z(before)?", "unknown macro"},
		{"unknown type", "version:H,create_operation_id:", "version:ZZ,create_operation_id:", "unknown type"},
		{"unknown field suffix", "semantic_result:T |", "semantic_result:T?? |", "unsupported field/type/suffix"},
		{"unknown macro suffix", "F(before)?", "F(before)??", "unsupported macro nullable suffix"},
		{"double special macro suffix", "S(incoming),A?", "S(incoming),A??", "unsupported macro nullable suffix"},
		{"unbalanced macro", "S(incoming),A?", "S(incoming,A?", "parentheses"},
		{"unknown inline generated", "previous_ordinal:I generated(ordinal-1)", "previous_ordinal:I generated(ordinal+1)", "unsupported inline generated"},
		{"empty generated expression", "previous_ordinal:I generated(ordinal-1)", "previous_ordinal:I generated()", "empty generated expression"},
		{"unexpected placeholder", "semantic_result:T |", "semantic_result:T generated? |", "unsupported generated? placeholder"},
		{"missing generated", genRow + "\n", "", "generated tail requires 18"},
		{"duplicate generated", genRow, genRow + "\n" + genRow, "duplicate generated expression"},
		{"mismatched generated branch", genRow, strings.Replace(genRow, "kind = 'request_birth'", "kind = 'attempt_birth'", 1), "does not match"},
		{"mismatched generated source", "CASE WHEN cause_kind = 'normal_cost_decision' THEN cause_source_id ELSE NULL END", "CASE WHEN cause_kind = 'normal_cost_decision' THEN source_id ELSE NULL END", "mismatched source columns"},
		{"missing generated input column", "kind:T,source_id:T,created_xid:X；随后", "kind:T,wrong_id:T,created_xid:X；随后", "missing ordinary TEXT"},
		{"missing inline ordinal input", "id:T,attempt_id:T,ordinal:I,previous_node_id:", "id:T,attempt_id:T,wrong_ordinal:I,previous_node_id:", "requires ordinary BIGINT"},
		{"generated duplicates ordinary column", "command_operation_id:T generated?", "command_operation_id:T?", "duplicates an inline or ordinary column"},
		{"unknown generated table", genRow, strings.Replace(genRow, "pp_root_steps", "pp_missing_table", 1), "unknown table"},
		{"unknown tail suffix", "；随后5列cause discriminator", "；随后5列anything", "unsupported generated tail"},
		{"wrong tail count", "；随后5列cause discriminator", "；随后4列cause discriminator", "requires 4 columns, got 5"},
		{"long table", "| pp_operation_roots |", "| pp_" + strings.Repeat("a", 61) + " |", "exceeds 63 bytes"},
		{"long column", "semantic_result:T |", strings.Repeat("a", 64) + ":T |", "exceeds 63 bytes"},
		{"long expanded prefix", "F(before)?", "F(" + strings.Repeat("a", 63) + ")?", "exceeds 63 bytes"},
		{"malformed markdown row", genRow, "+" + genRow, "malformed table row"},
		{"extra markdown table", "quote_selected_at是DB实际选价语句", "| bad | table |\nquote_selected_at是DB实际选价语句", "unexpected additional markdown table"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if !strings.Contains(source, tc.old) {
				t.Fatalf("mutation source not found: %q", tc.old)
			}
			changed := strings.Replace(source, tc.old, tc.replacement, 1)
			_, err := parseContract(changed)
			if err == nil || !strings.Contains(err.Error(), tc.errorPart) {
				t.Fatalf("got error %v, want %q", err, tc.errorPart)
			}
		})
	}
}

func TestStaticManifestMatchesDesign(t *testing.T) {
	layout, err := parseContract(schemaContract(t))
	if err != nil {
		t.Fatal(err)
	}
	want, err := encodeManifest(layout)
	if err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(filepath.Join("..", "..", manifestPath))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, want) {
		t.Fatal("tracked design-only manifest drifted; inspect columns before explicit --write")
	}
	if !bytes.Contains(got, []byte(`"generated_expression": null`)) {
		t.Fatal("ordinary columns must carry an explicit null generated_expression")
	}
}

func TestCLIReadOnlyAndExplicitWrite(t *testing.T) {
	root := t.TempDir()
	sourcePath := filepath.Join(root, contractPath)
	if err := os.MkdirAll(filepath.Dir(sourcePath), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(sourcePath, []byte(schemaContract(t)), 0644); err != nil {
		t.Fatal(err)
	}
	before := treeSnapshot(t, root)
	if err := run([]string{"--root", root}, io.Discard, io.Discard); err == nil || !strings.Contains(err.Error(), "read static manifest") {
		t.Fatalf("missing static file should fail: %v", err)
	}
	if !reflect.DeepEqual(before, treeSnapshot(t, root)) {
		t.Fatal("default check changed files when the manifest was absent")
	}
	var out bytes.Buffer
	if err := run([]string{"--root", root, "--write"}, &out, io.Discard); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "WROTE") || !strings.Contains(out.String(), "design only, no DDL/keys/ACL/reader/catalog attestation") {
		t.Fatalf("missing status/scope: %s", out.String())
	}
	path := filepath.Join(root, manifestPath)
	stamp := time.Unix(12345, 0)
	if err := os.Chtimes(path, stamp, stamp); err != nil {
		t.Fatal(err)
	}
	before = treeSnapshot(t, root)
	out.Reset()
	if err := run([]string{"--root", root}, &out, io.Discard); err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(out.String(), "PASS") || !reflect.DeepEqual(before, treeSnapshot(t, root)) {
		t.Fatal("default passing check wrote files or omitted PASS")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	changed := bytes.Replace(data, []byte(`"schema": 1`), []byte(`"schema": 99`), 1)
	if err := os.WriteFile(path, changed, 0644); err != nil {
		t.Fatal(err)
	}
	before = treeSnapshot(t, root)
	if err := run([]string{"--root", root}, io.Discard, io.Discard); err == nil || !strings.Contains(err.Error(), "static manifest differs") {
		t.Fatalf("fixture drift should fail: %v", err)
	}
	if !reflect.DeepEqual(before, treeSnapshot(t, root)) {
		t.Fatal("default failing check rewrote the static file")
	}
	if err := run([]string{"--root", root, "--write"}, io.Discard, io.Discard); err != nil {
		t.Fatal(err)
	}
	if got, _ := os.ReadFile(path); !bytes.Equal(got, data) {
		t.Fatal("explicit write did not produce the reviewed canonical bytes")
	}
	if err := os.WriteFile(sourcePath, []byte("invalid contract"), 0644); err != nil {
		t.Fatal(err)
	}
	before = treeSnapshot(t, root)
	if err := run([]string{"--root", root, "--write"}, io.Discard, io.Discard); err == nil {
		t.Fatal("invalid input must not be written")
	}
	if !reflect.DeepEqual(before, treeSnapshot(t, root)) {
		t.Fatal("explicit write changed files after parser failure")
	}
}

func treeSnapshot(t *testing.T, root string) map[string]string {
	t.Helper()
	result := make(map[string]string)
	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		result[rel] = fmt.Sprintf("%s:%d:%x", info.Mode(), info.ModTime().UnixNano(), sha256.Sum256(data))
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return result
}

func TestCLIRejectsUnknownAndPositionalArguments(t *testing.T) {
	for _, args := range [][]string{{"--unknown"}, {"extra"}} {
		if err := run(args, io.Discard, io.Discard); err == nil {
			t.Fatalf("accepted args %v", args)
		}
	}
}
